"use client";
import { useEffect, useState } from "react";

/** Device voices may arrive after the editor first mounts. */
export function useAgentVoices(language = "auto"): SpeechSynthesisVoice[] {
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  useEffect(() => {
    const synth = window.speechSynthesis;
    if (!synth) return;
    const update = () => setVoices(synth.getVoices().filter((voice) => voice.localService));
    update();
    synth.addEventListener("voiceschanged", update);
    return () => synth.removeEventListener("voiceschanged", update);
  }, []);
  return language === "auto" ? voices : voices.filter((voice) =>
    voice.lang.toLowerCase().split(/[-_]/)[0] === language.toLowerCase(),
  );
}

const PREVIEW_TEXT: Record<string, string> = {
  en: "Hello. I’m ready to help.",
  tr: "Merhaba. Yardım etmeye hazırım.",
  es: "Hola. Estoy listo para ayudar.",
  fr: "Bonjour. Je suis prêt à vous aider.",
