    {onRemove && <IconButton unstyled icon={DismissIcon} aria-label={`Remove ${attachment.name}`} onClick={onRemove} disabled={uploading} className={cx("absolute start-[35px] top-[3px] inline-flex size-4 shrink-0 cursor-pointer select-none items-center justify-center rounded-full outline-none transition-[opacity,filter,color] duration-300 ease-out focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2", image ? "bg-white/50 text-text-white backdrop-blur-[2px] hover:text-text-white" : "bg-background-tertiary-default/50 text-foreground-icon-secondary hover:text-text-primary", uploading ? "pointer-events-none opacity-0 blur-[3px]" : "opacity-100 blur-[0px]")} />}
  </div>;
}
export interface ComposerAttachmentStripProps {
  attachments: readonly ComposerAttachment[];
  onRemove?: (id: string) => void;
  className?: string;
}
export function ComposerAttachmentStrip({ attachments, onRemove, className }: ComposerAttachmentStripProps) {
  return <AnimatePresence initial={false}>{attachments.length > 0 &&
    <motion.div key="attachments" initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: .28, ease: [.22, 1, .36, 1] }} className="overflow-hidden">
      <div className={cx("flex flex-wrap items-start gap-2 pb-1", className)}>
        <AnimatePresence>{attachments.map(attachment => <motion.div key={attachment.id} initial={{ opacity: 0, scale: .8, filter: "blur(4px)" }} animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }} exit={{ opacity: 0, scale: .8, filter: "blur(4px)" }} transition={{ duration: .28, ease: [.22, 1, .36, 1] }}>
