type Category = "Discover" | "Plugins" | "Bots" | "Installed";
/** Searchable workspace extensions and agent cards, with host-owned installation callbacks. */
export function SettingsMarketplace({
  onClose,
  items = DEFAULT_MARKETPLACE_ITEMS,
  installedIds,
  onInstalledChange,
  storageKey,
}: SettingsMarketplaceProps) {
  const [category, setCategory] = useState<Category>("Discover"),
    [query, setQuery] = useState(""),
    [selectedId, setSelectedId] = useState<string | null>(null);
  const { installed, change } = useMarketplaceInstallation({
    items,
    installedIds,
    onInstalledChange,
