    ? [{ id: agent.id + "-user", role: "user" as const, content: agent.prompt }]
    : []),
  ...(agent.reply
    ? [{ id: agent.id + "-reply", role: "assistant" as const, content: agent.reply }]
    : []),
];
const EXTRA_CHAT_AGENTS: ChatAgent[] = [
  {
