const configurationFor = (agent: AgentOption): AgentConfiguration => ({
  ...DEFAULT_AGENT_CONFIGURATION,
  name: agent.name,
  label: agent.label ?? agent.name,
  description: agent.description ?? "",
  color: agent.color,
  emotionColor: agent.emotionColor ?? agent.color,
  shape: agent.shape ?? "robot",
