export interface MultiAgentChatTemplateProps
  extends Pick<TemplateShellProps, "contained" | "className" | "account" | "team"> {
  agents?: ChatAgent[];
  models?: ComposerModel[];
  composer?: Omit<ComposerPanelProps, "value" | "onValueChange" | "onSubmit" | "onStop" | "busy">;
  onSend?: ConversationAdapter;
  agentConfiguration?: AgentConfiguration;
  defaultEditorOpen?: boolean;
  onAgentChange?: (configuration: AgentConfiguration) => void;
  createAgent?: () => ChatAgent;
  onAgentCreate?: (agent: ChatAgent) => void;
  onAgentUpdate?: (agentId: string, configuration: AgentConfiguration) => void;
  onEditorAgentChange?: (agentId: string) => void;
  marketplace?: Omit<SettingsMarketplaceProps, "onClose">;
}
export function MultiAgentChatTemplate({
  agents = DEFAULT_CHAT_AGENTS,
  models,
  composer,
  onSend,
  agentConfiguration,
  defaultEditorOpen = true,
  onAgentChange,
  createAgent,
  onAgentCreate,
  onAgentUpdate,
  onEditorAgentChange,
  marketplace,
  ...shell
}: MultiAgentChatTemplateProps = {}) {
  const fallback = DEFAULT_CHAT_AGENTS[0];
  const [overrides, setOverrides] = useState<Record<string, Partial<ChatAgent>>>({});
  const [createdAgents, setCreatedAgents] = useState<ChatAgent[]>([]);
  const [createdOrder, setCreatedOrder] = useState<string[]>([]);
  const pool = [
    ...createdAgents,
    ...agents,
    ...EXTRA_CHAT_AGENTS.filter((a) => !agents.some((b) => a.id === b.id)),
  ].map((a) => ({ ...a, ...overrides[a.id] }));
  const pickerOrder = [
    "design",
    "content",
    "marketing",
    "seo",
    "research",
    "security",
    "product",
    "cloud",
    "support",
    "data",
  ];
  const pickerPool = [...pool].sort(
    (a, b) =>
      (pickerOrder.indexOf(a.id) < 0 ? 100 : pickerOrder.indexOf(a.id)) -
      (pickerOrder.indexOf(b.id) < 0 ? 100 : pickerOrder.indexOf(b.id)),
  );
  const [activeId, setActiveId] = useState(agents[0]?.id ?? fallback.id);
  const active = pool.find((a) => a.id === activeId) ?? fallback;
  const [groups, setGroups] = useState<{ id: string; agentIds: string[] }[]>([]),
    [groupId, setGroupId] = useState<string | null>(null);
  const group = groups.find((g) => g.id === groupId);
  const participants = group
    ? group.agentIds.map((id) => pool.find((a) => a.id === id)).filter((a): a is ChatAgent => !!a)
    : [active];
  const title = group ? participants.map((a) => a.label || a.name).join(" + ") : active.name;
  const conversationId = group?.id ?? active.id;
  const initialEditor = agents.find((a) => a.id === "security") ?? agents[0] ?? fallback;
  const [editorId, setEditorId] = useState(initialEditor.id);
  const [configuration, setConfiguration] = useState(() => configurationFor(initialEditor));
  const configurations = useRef(new Map<string, AgentConfiguration>());
  const [query, setQuery] = useState(""),
    [search, setSearch] = useState(false),
    [editorOpen, setEditorOpen] = useState(defaultEditorOpen),
    [picker, setPicker] = useState(false),
    [marketplaceOpen, setMarketplaceOpen] = useState(false);
  const conversation = useConversationState({
    initialMessages: initial(active),
    onSend,
    demoReply: active.demoReply ?? active.reply,
    demoTiming: { thinkingMs: 2800, firstParticipantThinkingMs: 3600, chunkMs: 48 },
    agentId: active.id,
    participants: group
      ? participants.map((a) => ({ agentId: a.id, demoReply: a.demoReply ?? a.reply }))
      : undefined,
  });
  const histories = useRef(new Map<string, ConversationMessage[]>());
  const selectConversation = (id: string) => {
    histories.current.set(conversationId, settleConversationMessages(conversation.messages));
    const nextGroup = groups.find((g) => g.id === id);
    setGroupId(nextGroup?.id ?? null);
    if (!nextGroup) setActiveId(id);
    const agent = pool.find((a) => a.id === id) ?? fallback;
    conversation.reset(histories.current.get(id) ?? (nextGroup ? [] : initial(agent)));
  };
  const openEditor = (agent: AgentOption) => {
    setEditorId(agent.id);
    setConfiguration(configurations.current.get(agent.id) ?? configurationFor(agent));
    onEditorAgentChange?.(agent.id);
    setEditorOpen(true);
  };
  const startGroup = (selected: AgentOption[]) => {
    histories.current.set(conversationId, settleConversationMessages(conversation.messages));
    const id = `group-${crypto.randomUUID()}`;
    setGroups((old) => [{ id, agentIds: selected.map((a) => a.id) }, ...old]);
    setCreatedOrder((old) => [id, ...old]);
    setGroupId(id);
    conversation.reset([]);
  };
  const createNewAgent = () => {
    histories.current.set(conversationId, settleConversationMessages(conversation.messages));
    let number = 2;
    while (pool.some((a) => a.name === `Product planner ${number}`)) number++;
    const preset = pool.find((a) => a.id === "product") ?? EXTRA_CHAT_AGENTS[0];
    const agent = createAgent?.() ?? {
      ...preset,
      id: `agent-${crypto.randomUUID()}`,
      name: `Product planner ${number}`,
      label: "",
      description: "",
      summary: "Start a conversation",
      prompt: "",
      reply: "",
      demoReply: preset.reply,
    };
    if (pool.some((existing) => existing.id === agent.id)) {
      selectConversation(agent.id);
      openEditor(agent);
      return;
    }
    setCreatedAgents((old) => [agent, ...old]);
    setCreatedOrder((old) => [agent.id, ...old]);
    setGroupId(null);
    setActiveId(agent.id);
    conversation.reset([]);
    onAgentCreate?.(agent);
    openEditor(agent);
  };
  const navigation = (onNavigate: () => void) => (
    <ConversationList
      selectedId={conversationId}
      query={query}
      onSelect={(id) => {
        selectConversation(id);
        onNavigate();
      }}
      items={[
        ...createdOrder.map((id) => {
          const group = groups.find((g) => g.id === id);
          if (group) {
            const members = group.agentIds
              .map((id) => pool.find((a) => a.id === id))
              .filter((a): a is ChatAgent => !!a);
            return {
              id: group.id,
              name: members.map((a) => a.label || a.name).join(" + "),
              summary:
                (group.id === groupId
                  ? conversation.messages
                  : histories.current.get(group.id)
                )?.at(-1)?.content ?? "Start a conversation",
              agents: members,
            };
          }
          const agent = pool.find((a) => a.id === id)!;
          return { id: agent.id, name: agent.name, summary: agent.summary, agents: [agent] };
        }),
        ...agents
          .map((a) => pool.find((p) => p.id === a.id) ?? a)
          .map((a) => ({ id: a.id, name: a.name, summary: a.summary, agents: [a] })),
      ]}
    />
  );
  const editorBody = (
    <AgentCreator
      value={agentConfiguration ?? configuration}
      onChange={(next) => {
        setConfiguration(next);
        configurations.current.set(editorId, next);
        if (!agentConfiguration)
          setOverrides((old) => ({
            ...old,
            [editorId]: {
              ...old[editorId],
              name: next.name,
              label: next.label,
              description: next.description,
              color: next.color,
              emotionColor: next.emotionColor,
              shape: next.shape,
            },
          }));
        onAgentChange?.(next);
        onAgentUpdate?.(editorId, next);
      }}
      onClose={() => setEditorOpen(false)}
    />
  );
  return (
    <>
      <SettingsModal
        isOpen={marketplaceOpen}
        onClose={() => setMarketplaceOpen(false)}
        defaultPage="marketplace"
        marketplace={marketplace}
      />
      <TemplateShell
        {...shell}
        variant="workspace"
        navigationBreakpoint="md"
        title={title}
        navigation={({ onNavigate }) => navigation(onNavigate)}
        sidebarOptions={{
          settings: { marketplace: marketplace ?? {} },
          showThemeToggle: false,
          className: "p-[7px]",
          header: ({ onNavigate }) => (
            <div className="flex items-center gap-2">
              {search ? (
                <Input
                  aria-label="Search conversations"
                  placeholder="Search"
                  value={query}
                  onChange={setQuery}
                />
              ) : (
                <>
                  <IconButton
                    icon={RiSearchLine}
                    className="w-auto min-w-0 flex-1 rounded-full border-0 bg-background-tertiary-default shadow-none"
                    aria-label="Search conversations"
                    onClick={() => setSearch(true)}
                  />
                  <IconButton
                    icon={RiStore2Line}
                    className="w-auto min-w-0 flex-1 rounded-full border-0 bg-background-tertiary-default shadow-none"
                    aria-label="Agent store"
                    onClick={() => {
                      onNavigate();
                      setMarketplaceOpen(true);
                    }}
                  />
                  <AgentCreateMenu
                    onCreate={() => {
                      onNavigate();
                      createNewAgent();
                    }}
                    onGroup={() => {
                      onNavigate();
                      setPicker(true);
                    }}
                  />
                </>
              )}
            </div>
          ),
        }}
        workspaceHeader={({ onOpenNavigation, navigationTriggerRef, navigationOpen }) => (
          <ConversationTopBar
            title={title}
            menuClassName="md:hidden"
            avatar={
              group ? (
                <AgentAvatarStack agents={participants} size="compact" />
              ) : (
                <AgentAvatar
                  color={active.color}
                  shape={active.shape}
                  className="size-5 rounded-md"
                />
              )
            }
            onOpenNavigation={onOpenNavigation}
            navigationTriggerRef={navigationTriggerRef}
            navigationOpen={navigationOpen}
            onOptions={() => openEditor(active)}
            actions={
              <AgentConversationActions
                participants={participants}
                transcript={conversation.messages
                  .map((m) => `${m.role}: ${m.content}`)
                  .join("\n\n")}
                onEdit={openEditor}
                onStartGroup={() => setPicker(true)}
              />
            }
          />
        )}
        panel={
          <AgentEditorPanel isOpen={editorOpen} onOpenChange={setEditorOpen}>
            {editorBody}
          </AgentEditorPanel>
        }
        overlays={
          <>
            <AgentPicker
              isOpen={picker}
              onOpenChange={setPicker}
              agents={pickerPool}
              initialSelectedIds={participants.map((a) => a.id)}
              onStart={startGroup}
            />
          </>
        }
      >
        {!conversation.messages.length ? (
          <div
            aria-label="Messages"
            tabIndex={0}
            className="flex min-h-0 flex-1 items-center justify-center overflow-y-auto px-6 text-center outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring"
          >
            <div className="flex flex-col items-center gap-4">
              <AgentAvatarStack agents={participants} />
              <div className="flex flex-col items-center gap-1.5">
                <h1 className="text-title-3-semibold text-text-primary">
                  {group ? "A few minds. One conversation." : `Say hello to ${active.name}`}
                </h1>
                {group && (
                  <p className="max-w-[420px] text-body-regular text-text-secondary">
                    {participants.map((a) => a.name).join(", ")} are here. Send a message to get
                    everyone’s perspective.
                  </p>
                )}
              </div>
            </div>
          </div>
        ) : (
          <ConversationMessages
            key={conversationId}
            messages={conversation.messages}
            renderAuthor={(message) => {
              const agent = pool.find((a) => a.id === (message.agentId ?? active.id));
              return agent
                ? {
                    label: agent.name,
                    avatar: (
                      <AgentAvatar color={agent.color} shape={agent.shape} className="size-5" />
                    ),
                    onSelect: () => openEditor(agent),
                  }
                : undefined;
            }}
          />
        )}
        {conversation.error && (
          <p role="alert" className="px-4 text-body-regular text-status-rose-text">
            {conversation.error}
          </p>
        )}
        <div className="shrink-0 p-1">
          <ComposerPanel
            {...composer}
            expandedOnMobile
            defaultModel={composer?.defaultModel ?? (!models && !composer?.models ? "fable-5" : undefined)}
            defaultPermission={composer?.defaultPermission ?? "bypass"}
            status={composer?.status ?? null}
            className={cx("max-w-none", composer?.className)}
            surfaceClassName={cx("rounded-[var(--radius-2-5xl)]", composer?.surfaceClassName)}
            models={models ?? composer?.models}
            value={conversation.input}
            onValueChange={conversation.setInput}
            onSubmit={(text) => void conversation.send(text)}
            busy={conversation.busy}
            onStop={conversation.stop}
          />
        </div>
      </TemplateShell>
    </>
  );
}

"use client";
import { motion } from "motion/react";
import { type ReactNode, type Ref } from "react";
import { Button } from "../../base/buttons/button";
import { cx } from "@/lib/cx";

/** Shared compact navigation reveal, measured from the rendered preview. */
export const TEMPLATE_NAVIGATION_TRANSITION = { duration: 0.325, ease: "easeInOut" } as const;

export interface TemplateContentFrameProps {
  children: ReactNode;
  variant?: "dashboard" | "workspace";
  className?: string;
  navigationOpen?: boolean;
  onCloseNavigation?: () => void;
  closeRef?: Ref<HTMLButtonElement>;
  contained?: boolean;
  columnClassName?: string;
}

/** Page content scrolls inside the viewport on compact screens and inside contained previews. */
export function TemplateContentFrame({
  children,
  variant = "dashboard",
  className,
  navigationOpen = false,
  onCloseNavigation,
  closeRef,
  contained,
  columnClassName,
}: TemplateContentFrameProps) {
  return (
    <motion.main
      initial={false}
      animate={{ x: navigationOpen ? 272 : 0, borderRadius: navigationOpen ? 32 : 0 }}
      transition={TEMPLATE_NAVIGATION_TRANSITION}
      className={cx(
        "relative z-20 flex min-h-0 min-w-0 flex-1 justify-center overflow-x-hidden overflow-y-auto bg-background-full p-3 will-change-transform sm:pt-6 lg:z-0 lg:transform-none! lg:rounded-none!",
        !contained && variant !== "workspace" && "lg:overflow-visible",
        variant === "workspace" &&
          "flex-col justify-start gap-2 overflow-hidden p-0 sm:pt-0 lg:overflow-hidden",
        className,
      )}
    >
      <motion.div
        initial={false}
        animate={{ opacity: navigationOpen ? 1 : 0 }}
        transition={TEMPLATE_NAVIGATION_TRANSITION}
        className={cx(
          "absolute inset-0 z-50 rounded-[inherit] lg:hidden",
          !navigationOpen && "pointer-events-none",
        )}
      >
        <Button
          unstyled
          type="button"
          ref={closeRef}
          aria-label="Close navigation"
          tabIndex={navigationOpen ? 0 : -1}
          onClick={onCloseNavigation}
          className="absolute inset-0 cursor-pointer rounded-[inherit] bg-black/10 dark:bg-white/5"
        />
      </motion.div>
      <div
        data-template-content=""
        inert={navigationOpen || undefined}
        className={cx(
          variant === "workspace"
            ? "flex min-h-0 min-w-0 flex-1 gap-3 overflow-hidden"
            : "flex w-full max-w-[1300px] flex-col gap-2.5",
          columnClassName,
        )}
      >
        {children}
      </div>
    </motion.main>
  );
}

"use client";
import { RiGroupLine, RiMenuLine } from "@remixicon/react";
import { motion } from "motion/react";
import { type ComponentProps, type ReactNode, type Ref, useEffect, useRef, useState } from "react";
import { IconButton } from "../../base/buttons/icon-button";
import { cx } from "@/lib/cx";
import {
  DASHBOARD_NAV,
  DashboardSidebar,
  type DashboardNavItem,
} from "../dashboard/dashboard-sidebar";
import { type DashboardAccount } from "../dashboard/dashboard-identity";
import { TemplateContentFrame, TEMPLATE_NAVIGATION_TRANSITION } from "./template-content-frame";
import { TemplateTopBar, type TemplateTopBarProps } from "./template-top-bar";

export interface TemplateShellProps
  extends Omit<
    TemplateTopBarProps,
    "navigationOpen" | "onOpenNavigation" | "navigationTriggerRef"
  > {
  variant?: "dashboard" | "workspace";
  navigationBreakpoint?: "md" | "lg";
  sidebarOptions?: Pick<
    NonNullable<ComponentProps<typeof DashboardSidebar>>,
    "header" | "className" | "showThemeToggle" | "settings"
  >;
  workspaceHeader?: (controls: {
    onOpenNavigation: () => void;
    navigationOpen: boolean;
    navigationTriggerRef: Ref<HTMLButtonElement>;
  }) => ReactNode;
  teamFooter?: NonNullable<ComponentProps<typeof DashboardSidebar>>["teamFooter"];
  navigation?: NonNullable<ComponentProps<typeof DashboardSidebar>>["navigation"];
  panel?: ReactNode;
  resizer?: ReactNode;
  overlays?: ReactNode;
  selected?: string;
  children: ReactNode;
  contained?: boolean;
  className?: string;
  columnClassName?: string;
  hideHeader?: boolean;
  navigationPlacement?: "row" | "overlay";
  frameClassName?: string;
  navigationItems?: DashboardNavItem[];
  accounts?: DashboardAccount[];
}

const TEMPLATE_NAV = [
  ...DASHBOARD_NAV,
  { key: "hr", label: "HR Team", icon: RiGroupLine, href: "/templates/hr" },
];

/** Templates compose this navigation, top bar and content frame; page bodies only own their content. */
export function TemplateShell({
  variant = "dashboard",
  navigationBreakpoint = "lg",
  navigation,
  sidebarOptions,
  workspaceHeader,
  teamFooter,
  panel,
  resizer,
  overlays,
  selected = "home",
  children,
  contained,
  className,
  columnClassName,
  hideHeader,
  navigationPlacement = "row",
  frameClassName,
  navigationItems = TEMPLATE_NAV,
  accounts,
  ...topBar
}: TemplateShellProps) {
  const [navOpen, setNavOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  useEffect(() => {
    if (!navOpen && restoreFocus.current) {
      restoreFocus.current = false;
      triggerRef.current?.focus();
    }
  }, [navOpen]);
  const closeNavigation = () => {
    restoreFocus.current = true;
    setNavOpen(false);
  };
  useEffect(() => {
    if (!navOpen) return;
    closeRef.current?.focus();
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape" && !event.defaultPrevented) {
        restoreFocus.current = true;
        setNavOpen(false);
      }
    };
    window.addEventListener("keydown", escape);
    const desktop = window.matchMedia(
      navigationBreakpoint === "md" ? "(min-width:768px)" : "(min-width:1024px)",
    );
    const resized = () => {
      if (desktop.matches) setNavOpen(false);
    };
    desktop.addEventListener("change", resized);
    return () => {
      window.removeEventListener("keydown", escape);
      desktop.removeEventListener("change", resized);
    };
  }, [navOpen, navigationBreakpoint]);
  const sidebarProps = {
    ...sidebarOptions,
    items: navigationItems,
    navigation,
    teamFooter,
    selected,
    account: topBar.account,
    accounts,
    team: topBar.team,
  };
  return (
    <div
      className={cx(
        "relative flex w-full bg-background-full max-lg:overflow-hidden",
        contained ? "h-full min-h-[600px] overflow-hidden" : "h-dvh lg:h-auto lg:min-h-screen",
        variant === "workspace" && "gap-4 overflow-hidden p-3 lg:h-dvh lg:min-h-0",
        className,
      )}
    >
      {overlays}
      <div
        className={cx(
          "sticky top-3 z-10 hidden shrink-0 py-0 pl-3",
          navigationBreakpoint === "md" ? "md:block" : "lg:block",
          contained ? "my-3 h-[calc(100%-24px)]" : "h-[calc(100dvh-24px)]",
          variant === "workspace" && "static h-full p-0 my-0",
        )}
      >
        <DashboardSidebar {...sidebarProps} />
      </div>
      <div
        data-template-navigation="compact"
        aria-hidden={!navOpen}
        inert={!navOpen || undefined}
        className={cx(
          "start-0 z-10 flex w-[272px] py-3 ps-[6px]",
          navigationBreakpoint === "md" ? "md:hidden" : "lg:hidden",
          contained ? "absolute inset-y-0" : "fixed inset-y-0",
        )}
      >
        <motion.div
          initial={false}
