"use client";
import { useCallback, useEffect, useRef, useState, type AriaRole, type ReactNode, type Ref } from "react";
import { cx } from "@/lib/cx";

/** Keyboard-accessible vertical content with progressive edge blur and surface fades. */
export function VerticalScroll({
  children,
  "aria-label": ariaLabel,
  className,
  scrollClassName,
  scrollRef,
  role,
  tabIndex = 0,
  variant = "progressive",
}: {
  children: ReactNode;
  "aria-label": string;
  className?: string;
  scrollClassName?: string;
  scrollRef?: Ref<HTMLDivElement>;
  role?: AriaRole;
  tabIndex?: number;
  variant?: "progressive" | "model-picker";
}) {
  const ref = useRef<HTMLDivElement>(null);
  const attach = useCallback((element: HTMLDivElement | null) => {
    ref.current = element;
    if (typeof scrollRef === "function") scrollRef(element);
    else if (scrollRef) scrollRef.current = element;
  }, [scrollRef]);
  const [edges, setEdges] = useState({ top: 0, bottom: 0 });
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => {
      const clamp = (distance: number) => variant === "model-picker"
        ? Number(distance > 0)
        : Math.min(1, Math.max(0, distance / 24));
      const next = {
        top: clamp(element.scrollTop),
        bottom: clamp(element.scrollHeight - element.clientHeight - element.scrollTop),
      };
      setEdges((old) => old.top === next.top && old.bottom === next.bottom ? old : next);
    };
    const resize = new ResizeObserver(measure);
    const observe = () => {
      resize.disconnect();
      resize.observe(element);
      for (const child of element.children) resize.observe(child);
      measure();
    };
    observe();
    const mutations = new MutationObserver(observe);
    mutations.observe(element, { subtree: true, childList: true, characterData: true });
    element.addEventListener("scroll", measure, { passive: true });
    document.fonts?.addEventListener("loadingdone", measure);
    return () => {
      resize.disconnect();
      mutations.disconnect();
      element.removeEventListener("scroll", measure);
      document.fonts?.removeEventListener("loadingdone", measure);
    };
  }, [variant]);
  return (
    <div className={cx("relative min-h-0 flex-1", className)}>
      <div ref={attach} role={role} aria-label={ariaLabel} tabIndex={tabIndex}
        className={cx("h-full overflow-y-auto overscroll-contain outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring [scrollbar-width:none]", scrollClassName)}>
        {children}
      </div>
      {(variant === "model-picker" ? ["top"] as const : ["top", "bottom"] as const).map((edge) => {
        const direction = edge === "top" ? "to bottom" : "to top";
        const anchor = edge === "top" ? "top-0" : "bottom-0";
        const maskImage = `linear-gradient(${direction}, black, transparent)`;
        if (variant === "model-picker") return <div key={edge} aria-hidden="true" data-scroll-edge={edge}
          className="pointer-events-none absolute inset-x-0 top-0 z-10 h-8 transition-opacity duration-200 ease-out"
          style={{ opacity: edges.top }}>
          {([1, 3, 8] as const).map((blur, index) => <div key={blur} className="absolute inset-0" style={{
            backdropFilter: `blur(${blur}px)`,
            maskImage: index === 0 ? "linear-gradient(to bottom, black 0%, black 45%, transparent 100%)" : index === 1 ? "linear-gradient(to bottom, black 0%, black 25%, transparent 75%)" : "linear-gradient(to bottom, black 0%, transparent 50%)",
          }} />)}
          <div className="absolute inset-0 bg-linear-to-b from-background-primary-default via-background-primary-default/70 to-transparent" />
        </div>;
        return <div key={edge} aria-hidden="true" data-scroll-edge={edge}
          className={cx("pointer-events-none absolute inset-x-0 z-10", anchor)}>
          <div className={cx("absolute inset-x-0 h-6 backdrop-blur-[1px]", anchor)} style={{ opacity: edges[edge], maskImage }} />
          <div className={cx("absolute inset-x-0 h-4 backdrop-blur-[4px]", anchor)} style={{ opacity: edges[edge], maskImage }} />
          <div className={cx("absolute inset-x-0 h-6", anchor)} style={{ opacity: edges[edge], background: `linear-gradient(${direction}, var(--color-background-full), transparent)` }} />
        </div>;
      })}
    </div>
  );
}

